/**
 * The loader for the published RecomGame.
 *
 * GENERATED by tools/deploy.mjs in nobrinde-recomgame. Do not edit this file: it
 * is overwritten by the next deploy, and the repository it comes from is the
 * place a change belongs.
 *
 * WHAT IT DOES, in order:
 *   1. fetch the sealed catalogue and the key, from beside this file;
 *   2. check the envelope before asking the browser to decrypt anything;
 *   3. AES-256-GCM decrypt, gunzip, JSON.parse;
 *   4. hand the document to the widget with RecomGame.define().
 *
 * The key is fetched rather than written here, so rotating it is replacing one
 * file. It is NOT a secret: see the note at the top of tools/deploy.mjs.
 */

const NAME = 'recom-game';
const STAGE = '[game-load]';

export async function boot(options) {
  const container = options.container;
  const dataUrl = options.dataUrl;
  const keyUrl = options.keyUrl;

  /** @param {string} message */
  const note = (message) => {
    const line = document.createElement('p');
    line.className = 'boot-note';
    line.textContent = message;
    container.replaceChildren(line);
  };

  /** @param {string} label @param {string} where @param {unknown} error */
  const report = (label, where, error) => {
    const detail = error instanceof Error ? error.message : String(error);
    console.error(STAGE, label, where, error);
    note(label + ': ' + detail + '  (' + where + ')');
  };

  try {
    note('A carregar o catálogo…');

    const [sealedResponse, keyResponse] = await Promise.all([fetch(dataUrl), fetch(keyUrl)]);
    for (const [response, url, what] of [
      [sealedResponse, dataUrl, 'o catálogo selado'],
      [keyResponse, keyUrl, 'a chave']
    ]) {
      if (!response.ok) {
        note(
          'Não foi possível ler ' + what + '. O servidor respondeu ' + response.status +
            ' ' + response.statusText + ' a ' + url + '.'
        );
        console.error(STAGE, 'http', response.status, url);
        return false;
      }
    }

    const envelope = await sealedResponse.json();
    const keyFile = await keyResponse.json();

    if (!envelope || typeof envelope !== 'object' || typeof envelope.data !== 'string' || typeof envelope.iv !== 'string') {
      note('O ficheiro ' + dataUrl + ' não tem o formato que esta página espera.');
      console.error(STAGE, 'envelope', envelope);
      return false;
    }
    if (envelope.alg !== 'AES-256-GCM' || envelope.zip !== 'gzip') {
      note(
        'O catálogo foi selado com ' + String(envelope.alg) + '/' + String(envelope.zip) +
          ', que esta página não sabe abrir.'
      );
      return false;
    }
    if (!keyFile || typeof keyFile.key !== 'string') {
      note('O ficheiro ' + keyUrl + ' não traz uma chave.');
      return false;
    }
    if (typeof DecompressionStream !== 'function') {
      note('Este browser não sabe descomprimir o ficheiro do catálogo (DecompressionStream). Tente uma versão atual do Chrome, Firefox ou Safari.');
      return false;
    }

    /** @param {string} base64 */
    const bytes = (base64) => {
      const binary = atob(base64);
      const out = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) out[index] = binary.charCodeAt(index);
      return out;
    };

    const cryptoKey = await crypto.subtle.importKey('raw', bytes(keyFile.key), 'AES-GCM', false, ['decrypt']);
    const sealed = bytes(envelope.data);
    const gzipped = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: bytes(envelope.iv), tagLength: 128 },
      cryptoKey,
      sealed
    );

    let json;
    try {
      json = await new Response(
        new Blob([gzipped]).stream().pipeThrough(new DecompressionStream('gzip'))
      ).text();
    } catch (error) {
      report('O catálogo não descomprimiu', dataUrl, error);
      return false;
    }

    let document_;
    try {
      document_ = JSON.parse(json);
    } catch (error) {
      report('O catálogo não é JSON válido depois de aberto', dataUrl, error);
      return false;
    }

    const defined = window.RecomGame && window.RecomGame.define;
    if (typeof defined !== 'function') {
      note('O módulo do jogo não instalou window.RecomGame, por isso não há como lhe entregar o catálogo.');
      console.error(STAGE, 'window.RecomGame is', window.RecomGame);
      return false;
    }

    defined.call(window.RecomGame, document_);
    const element = document.querySelector(NAME);
    if (!element) {
      note('O catálogo foi lido, mas não há <' + NAME + '> nesta página.');
      return false;
    }

    /*
     * The revision is written onto the element rather than into the markup: it is
     * a fact about the bytes the browser actually received, which is what someone
     * testing a deployment needs to see when two caches disagree.
     */
    element.setAttribute('data-revision', options.revision);
    element.removeAttribute('aria-busy');
    container.replaceChildren();
    return true;
  } catch (error) {
    /*
     * A DOMException from AES-GCM lands here, and it is the ordinary outcome of a
     * key that does not match the blob — a rotated key half-deployed, or a cached
     * key beside a fresh catalogue. It is reported as what it is instead of being
     * allowed to become an unhandled rejection.
     */
    const name = error && typeof error === 'object' && 'name' in error ? String(error.name) : '';
    if (name === 'OperationError') {
      note(
        'O catálogo não abriu com a chave publicada ao lado. Isto acontece quando a chave e o ' +
          'catálogo são de compilações diferentes; recarregue a página e, se persistir, publique de novo.'
      );
      console.error(STAGE, 'decrypt failed', dataUrl);
      return false;
    }
    report('O jogo não arrancou', dataUrl, error);
    return false;
  }
}
